from fractions import Fraction
from pathlib import Path
P=Path(__file__).resolve();ROOT=P.parents[3];R=ROOT/'research'/'benincasa'/'results';x=json.loads((R/'cosmology_weighted_specialization_source_search.json').read_text());n=next(c for c in x['candidates'] if c['name']=='naive_01_11_projection');v=[Fraction(s) for s in n['candidate_image']];primitive=[z/Fraction(1,2) for z in v];assert primitive==[-1,3];assert not x['chain_map_found'] and not x['primitive_Xi_projection_found'];out={'schema':'marici.benincasa.cosmology-weighted-specialization-dpc.v1','problem':'Does the obvious 01/11 coordinate projection produce the primitive Xi boundary column?','bold_conjecture':'Identifying extension coordinates 01 and 11 with (Xi_log,-sigma123) sends the exact weighted Gysin trace to the primitive vector (1,1).','named_rivals':['the projection gives primitive (-1,3)','a source-derived basis change repairs it','no chain map labels these coordinates physically'],'risky_consequences':['the projected ratio must equal one','a source-derived coordinate identification and chain map must exist'],'strongest_falsification_attempt':{'exact_projection':[str(z) for z in v],'primitive_rescaling':[int(z) for z in primitive],'required_primitive':[1,1],'projective_ratio':'-1:3 rather than 1:1','chain_map_found':x['chain_map_found']},'disposition':{'status':'falsified','surviving_scope':'the exact weighted Gysin trace remains (0,-1/2,0,3/2) in its declared basis','missing_object':x['first_missing_typed_object']},'passed':True};(R/'cosmology_weighted_specialization_dpc.json').write_text(json.dumps(out,indent=2)+'\n');print(json.dumps(out,indent=2))
